[FormEventHandler(formStr(CredManCustCreditCollectionsParameters), FormEventType::Initialized)]
public static void CredManParameters_OnInitialized(xFormRun sender, FormEventArgs e)
{
    CredManDocumentStatusCheck documentStatus = CredManDocumentStatusCheck::METCreditCheck;
    CredManHoldType holdType = CredManHoldType::Credit;
    FormDataSource CredManTmpStatusCheckSetup_DS = sender.dataSource(formDataSourceStr(CredManCustCreditCollectionsParameters,CredManTmpStatusCheckSetup ));
    CredManTmpStatusCheckSetup creManTmpStatusCheckSetup = CredManTmpStatusCheckSetup_DS.cursor();




    CredManStatusCheckSetup StatusCheckSetupProforma = CredManStatusCheckSetup::METfind(holdType, documentStatus, NoYes::Yes);


    creManTmpStatusCheckSetup.CheckProforma = NoYes::No;
    creManTmpStatusCheckSetup.CheckProformaGraceDays = StatusCheckSetupProforma.GraceDays;

    CredManStatusCheckSetup StatusCheckSetup = CredManStatusCheckSetup::METfind(holdType, documentStatus, NoYes::No);
    creManTmpStatusCheckSetup.CheckPosting = StatusCheckSetup.RecId != 0;
    creManTmpStatusCheckSetup.CheckPostingGraceDays = StatusCheckSetup.GraceDays;

    creManTmpStatusCheckSetup.documentstatus = documentStatus;
    creManTmpStatusCheckSetup.insert();

    METCredManTmpStatusCheckSetupEventHandler::subscribe(CredManTmpStatusCheckSetup_ds);
}
